client_script:
frappe.web_form.after_load = function() {
  var doc = frappe.web_form.doc;
  if (doc && doc.name) {
    var refEl = document.createElement('div');
    refEl.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:#fff8e1;color:#f57f17;border-left:4px solid #fbc02d;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">R\u00e9f. AO : ' + doc.name + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(refEl);
  }
  var roles = (frappe.boot && frappe.boot.user && frappe.boot.user.roles) ? frappe.boot.user.roles : [];
  var state = (doc && (doc.workflow_state || doc.statut)) || 'Brouillon';
  var rules = {
    'signature_demandeur': { states: ['Brouillon'], roles: [] },
    'signature_daaf': { states: ['En attente DAAF'], roles: ['Responsable Comptable','DAAF','Purchase Manager','System Manager'] },
    'signature_dg': { states: ['En attente DG'], roles: ['Directeur G\u00e9n\u00e9ral','System Manager'] }
  };
  ['signature_demandeur','signature_daaf','signature_dg'].forEach(function(f){ try{ frappe.web_form.set_df_property(f,'read_only',1); }catch(e){} });
  Object.keys(rules).forEach(function(field) {
    var rule = rules[field];
    var stateOk = rule.states.indexOf(state) !== -1;
    var roleOk = rule.roles.length === 0 || rule.roles.some(function(r){ return roles.indexOf(r) !== -1; });
    if (stateOk && roleOk) { try{ frappe.web_form.set_df_property(field,'read_only',0); }catch(e){} }
  });
  if (doc && doc.statut) {
    var cm = {'Approuv\u00e9':'#2e7d32','Rejet\u00e9':'#c62828','Brouillon':'#757575','Envoy\u00e9':'#1565c0'};
    var c = cm[doc.statut] || '#e65100';
    var el = document.createElement('div');
    el.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:'+c+';color:#fff;border-radius:6px;display:inline-block;font-weight:700;">\u00c9tat\u00a0: '+doc.statut+'</div>';
    var w2 = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w2) w2.prepend(el);
  }
};
frappe.web_form.on('load', function(){
  var user = (frappe.session && frappe.session.user) ? frappe.session.user : null;
  if (!user || user === 'Guest') return;
  frappe.call({
    method: 'frappe.client.get_value',
    args: { doctype: 'Employee', filters: { user_id: user, status: 'Active' }, fieldname: ['name','employee_name','department'] },
    callback: function(r){
      if (!r || !r.message) return;
      var doc = frappe.web_form.doc;
      if (!doc.demandeur) frappe.web_form.set_value('demandeur', r.message.name);
      if (r.message.employee_name && !doc.demandeur_name) frappe.web_form.set_value('demandeur_name', r.message.employee_name);
      if (r.message.department && !doc.service) frappe.web_form.set_value('service', r.message.department);
    }
  });
});
